def is_bipartite(n, edges):
    g = [[0] * n for _ in range(n)]
    for u, v in edges:
        g[u][v] = 1
        g[v][u] = 1
    color = [-1] * n
    for s in range(n):
        if color[s] != -1:
            continue
        q = [s]
        color[s] = 0
        head = 0
        while head < len(q):
            u = q[head]
            head += 1
            for v in range(n):
                if g[u][v] == 1:
                    if color[v] == color[u]:
                        return False
                    if color[v] == -1:
                        color[v] = 1 - color[u]
                        q.append(v)
    return True

